style.css:
/* Futuristic Userstyle with mauve highlights */

body {
    background-color: #1b1b2f; /* Dark background with a slight blue tone */
    color: #d1d1e9; /* Soft light color for text */
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

/* Links with mauve color */
a {
    color: #b983ff; /* Mauve color */
    text-decoration: none;
}

a:hover {
    color: #d4b3ff; /* Lighter mauve on hover */
    text-decoration: underline;
}

/* Headers with futuristic look */
h1, h2, h3, h4, h5, h6 {
    color: #e0d8ff;
    border-bottom: 1px solid #b983ff;
}

/* Buttons with soft glow effect */
button {
    background-color: #302b63;
    color: #ffffff;
    border: 1px solid #b983ff;
    border-radius: 5px;
    padding: 10px 20px;
    cursor: pointer;
}

button:hover {
    background-color: #413b80;
    box-shadow: 0 0 10px #b983ff;
}

/* Inputs and text areas */
input, textarea {
    background-color: #252537;
    color: #ffffff;
    border: 1px solid #b983ff;
    padding: 10px;
    border-radius: 5px;
}

input:focus, textarea:focus {
    outline: none;
    box-shadow: 0 0 10px #b983ff;
}

/* Footer with a soft tone */
footer {
    background-color: #1f1f30;
    color: #b3b3cc;
    padding: 20px;
    text-align: center;
}
